      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo phân độ chảy máu mũi (Nhẹ - Vừa - Nặng) của Bộ môn Tai Mũi Họng - ĐHYHN, tiêu chuẩn quan trọng nhất trên lâm sàng để xác định chảy máu mũi mức độ nặng là sự thay đổi toàn trạng và rối loạn huyết động do mất máu cấp: bệnh nhân mệt lả, hốt hoảng hoặc lơ mơ, da xanh tái, niêm mạc nhợt nhạt, vã mồ hôi lạnh, tay chân lạnh, mạch nhanh nhỏ khó bắt (> 100-120 lần/phút), huyết áp tụt (HA tâm thu < 90 mmHg hoặc tụt > 20-30 mmHg so với HA nền), thiểu niệu/vô niệu, kèm theo lượng máu chảy thành dòng qua cả mũi trước và mũi sau không tự cầm, xét nghiệm Hb giảm sâu (< 70-80 g/L).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Sai): Huyết áp cao không phải là tiêu chuẩn phân loại chảy máu mũi mức độ nặng (thậm chí ở giai đoạn đầu chảy máu mũi nhẹ/vừa, huyết áp có thể tăng do nguyên nhân tăng huyết áp nền hoặc do tâm lý lo lắng, kích thích giao cảm; ngược lại khi đã mất máu nặng dẫn đến sốc giảm thể tích thì huyết áp sẽ tụt chứ không cao). Phương án B sẽ đúng nếu hỏi về 'Yếu tố nguy cơ / nguyên nhân toàn thân thường gặp gây chảy máu mũi ở người cao tuổi'.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc khuyết phương án C, D (thường là 'C. Chảy máu ra cửa mũi trước', 'D. Máu chảy thành giọt'). Đáp án chuẩn xác là A."
