      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nKhi tiếp nhận bệnh nhân chảy máu mũi, quy trình thăm khám và cận lâm sàng cấp cứu bao gồm: (1) Đánh giá ngay toàn trạng và dấu hiệu sinh tồn (đo mạch, huyết áp, nhịp thở, tri giác) để phát hiện sớm sốc mất máu hoặc cơn tăng huyết áp cấp cứu; (2) Khám Tai Mũi Họng (soi mũi trước, khám họng, nội soi mũi xoang) để xác định chảy máu mũi trước hay mũi sau và xử trí cầm máu tại chỗ; (3) Xét nghiệm máu cấp cứu bắt buộc: Công thức máu (đánh giá Hb, Hct, số lượng tiểu cầu), Nhóm máu (nếu chảy máu vừa - nặng) và Đông máu cơ bản (PT, APTT, Fibrinogen) để tầm soát rối loạn đông cầm máu. Chụp X-quang ngực thẳng không có giá trị trong chẩn đoán và xử trí cấp cứu chảy máu mũi.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Đúng nên không chọn): Đo mạch, huyết áp là bước bắt buộc đầu tiên để đánh giá huyết động và phát hiện sốc mất máu hoặc tăng huyết áp.\n- Phương án B (Đúng nên không chọn): Công thức máu và đông máu cơ bản là hai xét nghiệm thiết yếu để đánh giá mức độ thiếu máu và nguyên nhân rối loạn đông cầm máu.\n- Phương án C (Sai - là đáp án cần chọn): X-quang ngực thẳng không cần thiết trong phác đồ cấp cứu chảy máu mũi thông thường. Phương án này chỉ đúng khi bệnh nhân cần phân biệt với ho ra máu từ phế quản - phổi, nghi ngờ hít sặc máu vào phổi, hoặc chụp tiền phẫu thường quy trước khi gây mê toàn thân để phẫu thuật thắt mạch/mổ u.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc khuyết phương án D (ví dụ: 'D. Khám nội soi mũi họng đánh giá vị trí chảy máu'). Đáp án chuẩn xác là C."
