      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nChảy máu mũi sau (Posterior epistaxis) xuất phát từ phần sau của hốc mũi, nguyên nhân giải phẫu tuyệt đại đa số là do vỡ các nhánh của động mạch bướm khẩu cái (nhánh mũi sau ngoài cấp máu cho vùng đuôi cuốn mũi giữa, đuôi cuốn mũi dưới hợp thành đám rối Woodruff, hoặc nhánh vách ngăn sau cấp máu cho phần sau vách ngăn). Do ĐM bướm khẩu cái có khẩu kính lớn và áp lực dòng máu cao (nhánh tận của ĐM hàm trong), chảy máu từ mạch này thường chảy ồ ạt ra cửa mũi sau xuống họng và là đích tác động của phẫu thuật nội soi đốt/thắt ĐM bướm khẩu cái.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Động mạch sàng trước - Sai): Động mạch sàng trước (nhánh của ĐM mắt - hệ ĐM cảnh trong) đi qua ống sàng trước vào phần trước trên hốc mũi, cấp máu cho 1/3 trước trên thành ngoài và vách ngăn, đồng thời tham gia tạo nên điểm mạch Kiesselbach. ĐM sàng trước sẽ là đáp án đúng khi hỏi về chảy máu mũi trước/trên hoặc chảy máu mũi sau chấn thương vỡ xương chính mũi - khối bên xương sàng kèm chấn thương sọ mặt tầng trên.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K118 - PH):\nCâu hỏi gốc khuyết phương án C, D (thường là 'C. Động mạch sàng sau', 'D. Động mạch môi trên'). Đáp án chuẩn xác là A."
