      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nViêm tai giữa mạn tính không nguy hiểm (VTG mạn tính mủ nhầy) có các đặc điểm lâm sàng và nội soi kinh điển: (1) Chảy dịch tai từng đợt phụ thuộc vào các đợt viêm mũi họng, dịch nhầy trong hoặc đục, dính, kéo thành sợi, không thối; (2) Nội soi màng nhĩ: lỗ thủng luôn khu trú ở **phần màng căng (Pars tensa)** (thường hình tròn, bầu dục hoặc hình quả thận), **bờ lỗ thủng gọn, nhẵn, KHÔNG sát khung xương** (vẫn còn vành màng nhĩ/vòng sợi sụn Gerlach bao quanh), niêm mạc đáy hòm nhĩ màu hồng nhạt, ẩm hoặc hơi nề, không có polyp hay tổ chức hạt sùi và không có cholesteatoma; (3) Nghe kém kiểu dẫn truyền mức độ nhẹ đến trung bình. Ngược lại, **Lỗ thủng ở màng chùng (màng Shrapnell)** là dấu hiệu đặc trưng của **Viêm tai giữa mạn tính nguy hiểm (có cholesteatoma thượng nhĩ)**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Sai - là đáp án cần chọn): Lỗ thủng màng chùng không bao giờ gặp trong VTG mạn tính không nguy hiểm. Phương án này sẽ đúng khi hỏi về đặc điểm nội soi của 'Viêm tai giữa mạn tính nguy hiểm (thể thượng nhĩ / có cholesteatoma)'.\n- Phương án B (Mủ nhầy - Đúng của VTG mạn không nguy hiểm nên không chọn).\n- Phương án C (Lỗ thủng màng căng, bờ gọn, không sát xương - Đúng của VTG mạn không nguy hiểm nên không chọn).",
