      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo định nghĩa của Tổ chức Y tế Thế giới (WHO) và Giáo trình Tai Mũi Họng - Đại học Y Hà Nội, Viêm tai giữa mạn tính (Chronic Otitis Media) là tình trạng viêm nhiễm của tai giữa (hòm nhĩ, thông bào chũm, vòi nhĩ) có kèm lỗ thủng màng nhĩ không tự liền và chảy dịch tai kéo dài liên tục hoặc từng đợt **trên 12 tuần (tức là trên 3 tháng)**. Mốc thời gian dưới 3 tuần là viêm tai giữa cấp tính, từ 3 tuần đến 12 tuần là viêm tai giữa bán cấp. Do đó nói viêm tai giữa mạn tính 'kéo dài trên 2 tháng' là sai về tiêu chuẩn thời gian chẩn đoán.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Đúng nên không chọn): Viêm tai giữa mạn tính mủ nhầy chính là viêm tai giữa mạn tính không nguy hiểm.\n- Phương án B (Sai - là đáp án cần chọn): Sai vì mốc chuẩn chẩn đoán mạn tính của cả Viêm tai giữa mạn tính và Viêm mũi xoang mạn tính theo giáo trình ĐHYHN đều là **trên 12 tuần (trên 3 tháng)** chứ không phải 2 tháng.\n- Phương án C (Đúng nên không chọn): Trong VTG mạn tính không nguy hiểm, bệnh tích giải phẫu bệnh chỉ khu trú ở lớp niêm mạc hòm nhĩ (không ăn mòn xương con hay thành xương hòm nhĩ - xương chũm).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc khuyết phương án D (được ghi trong note là 'D. Không gây biến chứng nội sọ'). Đáp án sai cần chọn giữ nguyên là B."
