      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrong Viêm tai giữa mạn tính không nguy hiểm (VTG mạn tính mủ nhầy), bệnh tích chỉ khu trú ở niêm mạc và gây thủng phần màng căng của màng nhĩ, trong khi chuỗi xương con (búa - đe - bàn đạp) về cơ bản vẫn còn nguyên vẹn và tai trong (ốc tai) chưa bị tổn thương. Do chỉ giảm diện tích rung động của màng nhĩ nên trên thính lực đồ đơn âm (Pure-tone audiometry), bệnh nhân biểu hiện **Nghe kém (điếc) dẫn truyền mức độ nhẹ đến vừa** (đường cốt đạo bình thường nằm trên mức 20-25 dB, đường khí đạo hạ thấp khoảng 25-45 dB tạo khoảng cách khí - xương ABG khoảng 15-30 dB).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Điếc dẫn truyền nặng - Sai): Điếc dẫn truyền nặng (mức mất thính lực đường khí 50-60 dB, ABG > 40 dB) chỉ xảy ra khi có gián đoạn hoặc tiêu hủy chuỗi xương con (như tiêu ngành xuống xương đe, tiêu chỏm xương bàn đạp) - thường gặp trong **Viêm tai giữa mạn tính nguy hiểm (có cholesteatoma)**.\n- Phương án C (Điếc tiếp nhận - Sai): Điếc tiếp nhận là tổn thương ốc tai hoặc dây thần kinh số VIII (lão thính, điếc nghề nghiệp, nhiễm độc tai do thuốc, viêm mê nhĩ).\n- Phương án D (Điếc hỗn hợp - Sai): Điếc hỗn hợp (cả đường khí và đường xương đều hạ thấp, còn khoảng ABG) gặp trong VTG mạn tính nguy hiểm giai đoạn muộn khi độc tố hoặc cholesteatoma đã xâm lấn qua cửa sổ bầu dục/cửa sổ tròn hoặc ăn mòn ống bán khuyên gây tổn thương tai trong.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là A."
