      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nViêm tai giữa mạn tính nguy hiểm (còn gọi là VTG mạn tính mủ thối / VTG mạn tính có cholesteatoma) đặc trưng bởi tổn thương tiêu xương ở thượng nhĩ - sào bào - sào đạo - xương chũm và chuỗi xương con. Đặc điểm nội soi màng nhĩ của VTG mạn tính nguy hiểm bao gồm: (1) Lỗ thủng ở **màng chùng (màng Shrapnell)** sát khung xương thượng nhĩ (phương án B); hoặc (2) Lỗ thủng ở **góc sau trên của màng căng** hoặc thủng toàn bộ màng căng nhưng **bờ nham nhở, sát khung xương** (tiêu mất vòng sợi sụn Gerlach, lộ lớp xương ống tai/tường dây VII) (phương án D); (3) Qua lỗ thủng thấy các vảy trắng óng ánh như xà cừ xếp lớp đồng tâm của khối **Cholesteatoma** (phương án C), hoặc polyp/tổ chức hạt sùi ở góc sau trên/thượng nhĩ. Ngược lại, **Lỗ thủng màng căng không sát xương** (bờ gọn, còn vành màng nhĩ) là đặc trưng của VTG mạn tính KHÔNG nguy hiểm.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Sai - là đáp án cần chọn): Lỗ thủng màng căng không sát xương là đặc điểm của VTG mạn tính mủ nhầy (không nguy hiểm).\n- Phương án B, C, D (Đúng là đặc điểm của VTG mạn tính nguy hiểm nên không chọn).",
