      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrong Viêm tai giữa mạn tính nguy hiểm (có cholesteatoma), tổn thương màng nhĩ trên nội soi có thể gặp ở các hình thái: (1) Lỗ thủng ở màng chùng (màng Shrapnell - tương ứng với túi Prussak ở thượng nhĩ ngoài); (2) Lỗ thủng ở góc sau trên của màng căng sát khung xương, thường kèm theo **polyp hoặc tổ chức hạt viêm sùi ở góc sau trên** che lấp khối cholesteatoma bên trong thượng nhĩ - sào đạo; (3) Lỗ thủng rộng toàn bộ màng căng, bờ nham nhở, sát khung xương, ăn mòn tường thượng nhĩ. Trong khi đó, **Lỗ thủng vị trí trước trên (hoặc trước dưới - vùng vòi nhĩ), bờ gọn, không sát xương** là hình ảnh điển hình của VTG mạn tính không nguy hiểm (liên quan trực tiếp đến bệnh lý vòi nhĩ - mũi họng).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Lỗ thủng màng chùng - Đúng trong VTG mạn nguy hiểm nên không chọn): Phản ánh cholesteatoma thượng nhĩ nguyên phát.\n- Phương án B (Polyp ở màng căng vị trí sau trên - Đúng trong VTG mạn nguy hiểm nên không chọn): Polyp/tổ chức hạt ở góc sau trên hoặc màng chùng là dấu hiệu chỉ điểm có viêm xương/cholesteatoma ở thượng nhĩ phía sau.\n- Phương án C (Sai - là đáp án cần chọn): Lỗ thủng phần trước màng căng không sát xương là tổn thương lành tính của VTG mạn mủ nhầy (thể vòi nhĩ).\n- Phương án D (Thủng toàn bộ màng căng, sát xương - Đúng trong VTG mạn nguy hiểm nên không chọn).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 2):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là C."
