      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nMủ tai trong Viêm tai giữa mạn tính nguy hiểm (có cholesteatoma / viêm xương) có các tính chất kinh điển: (1) Lượng mủ thường không nhiều nhưng chảy liên tục và có **mùi thối khẳn** rất đặc trưng (như mùi cóc chết - do vi khuẩn kỵ khí, Proteus, Pseudomonas aeruginosa phân hủy chất keo xương và keratin); (2) Mủ đặc hoặc **lổn nhổn vón cục như bã đậu** trắng vàng, khi cho vào nước thì tan ra thành các hạt nhỏ lơ lửng; (3) Trên mặt nước nổi lên các **váng óng ánh như mỡ** (do chứa các tinh thể cholesterol từ khối cholesteatoma). Ngược lại, tính chất **'Dính, có thể kéo dài thành sợi'** (và không tan trong nước, không thối) là tính chất của chất nhầy (mucin) do tế bào đài tiết ra trong **Viêm tai giữa mạn tính mủ nhầy (không nguy hiểm)**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A, B, C (Đúng là đặc điểm mủ của VTG mạn tính nguy hiểm nên không chọn).\n- Phương án D (Sai - là đáp án cần chọn): Dịch nhầy dẻo dính kéo dài thành sợi chỉ đúng khi mô tả dịch tai trong Viêm tai giữa mạn tính không nguy hiểm (mủ nhầy).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 2):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là D."
