      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nViêm tai giữa mạn tính nguy hiểm (còn gọi là viêm tai xương chũm mạn tính) có đặc điểm giải phẫu bệnh là tổn thương viêm xương, tiêu xương khu trú chủ yếu ở tầng trên của hòm nhĩ là **thượng nhĩ (epitympanum), sào đạo (aditus ad antrum) và sào bào - các thông bào xương chũm (mastoid antrum)**, kèm theo sự hiện diện của cholesteatoma (chiếm đa số nhưng không phải 100% mọi trường hợp vì một số ít ca chỉ có viêm xương hoại tử/tổ chức hạt/polyp tiêu xương mà chưa hình thành túi cholesteatoma điển hình). Về điều trị ngoại khoa, do bệnh tích nằm ở thượng nhĩ và xương chũm nên không thể chỉ mở sào bào - khoét xương chũm đơn thuần (Schwartze) như trong viêm xương chũm cấp, mà phải thực hiện phẫu thuật mở sào bào - thượng nhĩ hoặc khoét rỗng đá chũm bán phần/tiệt căn (hạ tường dây VII, phá cầu xương tạo một hốc mổ chung dẫn lưu ra ống tai ngoài) kết hợp chỉnh hình tai giữa.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Nhất định phải có cholesteatoma - Sai): Tuy cholesteatoma gặp trong phần lớn các trường hợp VTG mạn nguy hiểm, nhưng theo định nghĩa giáo trình, VTG mạn nguy hiểm bao gồm cả các trường hợp viêm xương hoại tử mạn tính (osteitis/granulation tissue) gây tiêu xương con và thành xương hòm nhĩ dù chưa có cholesteatoma.\n- Phương án C (Có thể phẫu thuật khoét xương chũm đơn thuần - Sai): Phẫu thuật khoét xương chũm đơn thuần (mở sào bào - xương chũm đơn thuần bảo tồn thành sau ống tai và không can thiệp thượng nhĩ - hòm nhĩ) chỉ đúng cho **Viêm xương chũm cấp tính**. Trong VTG mạn tính nguy hiểm bắt buộc phải can thiệp cả thượng nhĩ, hòm nhĩ và xương chũm (mở thượng nhĩ - sào bào kết hợp vá nhĩ hoặc khoét rỗng đá chũm).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 3):\nCâu hỏi gốc khuyết phương án D (ví dụ: 'D. Không gây biến chứng nội sọ' hoặc 'D. Điều trị nội khoa là chủ yếu'). Đáp án chuẩn xác là A."
