      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrên nội soi tai, hình ảnh đặc trưng của Viêm tai giữa mạn tính nguy hiểm là lỗ thủng ở màng chùng hoặc **lỗ thủng ở góc sau trên / thủng rộng toàn bộ màng căng, bờ lỗ thủng nham nhở, sát khung xương** (tiêu hủy vòng sợi sụn Gerlach), đáy hòm nhĩ bẩn có mủ thối, tổ chức hạt sùi/polyp hoặc các vảy trắng óng ánh của cholesteatoma, chuỗi xương con có thể bị ăn mòn cụt.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Xung huyết, không phồng, không có nón sáng - Sai): Đây là hình ảnh nội soi màng nhĩ của **Viêm tai giữa cấp tính giai đoạn xung huyết** (màng nhĩ hồng/đỏ dọc theo cán búa và ngoại vi, mất tam giác sáng).\n- Phương án C (Căng phồng như mặt kính đồng hồ, trắng bệch - Sai): Đây là hình ảnh nội soi của **Viêm tai giữa cấp mủ giai đoạn ứ mủ** toàn bộ hòm nhĩ.\n- Phương án D (Màng nhĩ trắng đục, căng phồng như vú bò ở phần sau trên - Sai): Đây là hình ảnh kinh điển của **Viêm tai giữa cấp mủ giai đoạn ứ mủ khu trú góc sau trên** (hoặc dấu hiệu xóa góc sau trên trong viêm xương chũm cấp).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 4):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D, phân biệt hình ảnh nội soi màng nhĩ giữa VTG mạn nguy hiểm và các giai đoạn của VTG cấp. Đáp án giữ nguyên là B."
