      "q": "Câu 44 (Câu 35 - K117 - PH). BN nữ 5 tuổi, bị chảy dịch tai mủ nhầy 2 năm nay. NS có thấy thủng màng căng, bờ không sát xương, niêm mạc hòm nhĩ sưng huyết. VA quá phát độ III. Cần điều trị gì ở BN này",
