      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nỞ bệnh nhân Viêm tai giữa mạn tính nguy hiểm (thủng toàn bộ màng căng, sát xương, có cholesteatoma), mục tiêu của phẫu thuật tai xương chũm hiện đại luôn bao gồm 2 nhiệm vụ: (1) **Lấy hết bệnh tích** (lấy bỏ hoàn toàn túi nền và chất cholesteatoma, xương viêm hoại tử ở thượng nhĩ - sào đạo - xương chũm để tạo tai khô an toàn, phòng ngừa biến chứng nội sọ/liệt mặt/viêm mê nhĩ); và (2) **Phục hồi chức năng nghe** (chỉnh hình chuỗi xương con bằng trụ dẫn tự thân hoặc nhân tạo PORP/TORP và tái tạo màng nhĩ trong cùng một thì hoặc ở thì 2). Do đó đáp án đầy đủ và chuẩn xác nhất là **B. Lấy hết bệnh tích + phục hồi chức năng nghe**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Chỉ lấy hết bệnh tích - Chưa đầy đủ): Trước đây phẫu thuật khoét rỗng đá chũm tiệt căn kinh điển chỉ tập trung lấy hết bệnh tích mà hy sinh chức năng nghe; nhưng theo giáo trình hiện hành của Bộ môn TMH - ĐHYHN, mục tiêu phẫu thuật bao gồm cả lấy sạch bệnh tích và bảo tồn/phục hồi tối đa chức năng nghe.\n- Phương án C, D (Chỉ phục hồi chức năng nghe / Chỉ vá màng nhĩ - Sai): Phục hồi chức năng nghe và vá màng nhĩ đơn thuần chỉ là mục tiêu của phẫu thuật trong **Viêm tai giữa mạn tính không nguy hiểm (mủ nhầy) đã khô tai**.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 4):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D, thống nhất với câu 36 về mục tiêu phẫu thuật VTG mạn tính có cholesteatoma. Đáp án giữ nguyên là B."
