      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nBệnh nhân có tiền sử chảy mủ tai từng đợt, khám thấy lỗ thủng màng căng, bờ không sát xương -> Chẩn đoán là **Viêm tai giữa mạn tính không nguy hiểm (mủ nhầy)**. Trong thể bệnh này, tổn thương chỉ khu trú ở niêm mạc, không có cholesteatoma ăn mòn xương và không đe dọa gây biến chứng nội sọ cấp tính. Nguyên tắc điều trị của Bộ môn TMH - ĐHYHN đối với VTG mạn không nguy hiểm: (1) Nếu tai đang chảy mủ: điều trị nội khoa và làm thuốc tai cho đến khi tai khô ổn định; (2) Nếu tai đang khô: không cần làm thuốc tai tại chỗ, giữ vệ sinh không để nước vào tai; (3) Chỉ định phẫu thuật vá nhĩ là phẫu thuật **có kế hoạch (chọn lọc)** sau khi đã điều trị ổn định các ổ viêm mũi họng và tai khô hoàn toàn nhằm cải thiện chức năng nghe và ngăn tái nhiễm. Vì vậy, nhận định **'B. Phẫu thuật càng sớm càng tốt'** là nhận định SAI (cần chọn cho câu hỏi TRỪ).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Không cần làm thuốc/can thiệp nội khoa tại chỗ vì mủ tai đang khô - Đúng với giai đoạn tai khô nên không chọn).\n- Phương án B (Sai - là đáp án cần chọn): 'Phẫu thuật càng sớm càng tốt' (không cần chờ hết mủ) là nguyên tắc điều trị ngoại khoa của **Viêm tai giữa mạn tính nguy hiểm (có cholesteatoma)**.\n- Phương án C (Phẫu thuật khi điều trị nội khoa ổn định - Đúng nguyên tắc vá nhĩ nên không chọn).\n- Phương án D (Phẫu thuật để cải thiện chức năng nghe - Đúng mục tiêu của vá nhĩ trong VTG mạn không nguy hiểm nên không chọn).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 3):\nHiệu đính câu khuyết đáp án: Câu hỏi hỏi 'BN có tiền sử chảy mủ tai nhiều năm thành từng đợt, khám thấy lỗ thủng màng căng không sát xương (VTG mạn không nguy hiểm), hiện tại tai khô... Hướng điều trị, TRỪ?'. Phân tích 4 phương án: trong VTG mạn không nguy hiểm (mủ nhầy), phẫu thuật vá nhĩ là phẫu thuật **có kế hoạch (chủ động)** khi tai đã khô ổn định nhằm cải thiện sức nghe và tránh tái nhiễm (hoặc nếu bệnh nhân lớn tuổi, lỗ thủng nhỏ, tai khô lâu năm không ảnh hưởng sinh hoạt thì có thể theo dõi, giữ khô tai không bắt buộc mổ ngay). Ngược lại, mệnh đề **'B. Phẫu thuật càng sớm càng tốt'** là chỉ định đặc trưng của **Viêm tai giữa mạn tính NGUY HIỂM (có cholesteatoma)** chứ không phải của VTG mạn không nguy hiểm! Do đó, đã bổ sung và xác định đáp án chuẩn cho câu 40 là **B**."
