      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Tai Mũi Họng - Đại học Y Hà Nội, tai giữa thông trực tiếp với vòm mũi họng qua vòi nhĩ (vòi Eustache). Sự thông khí và dẫn lưu bình thường của vòi nhĩ là điều kiện tiên quyết để phẫu thuật tai (đặc biệt là phẫu thuật vá nhĩ và chỉnh hình tai giữa) thành công. Nếu bệnh nhân còn các ổ viêm mạn tính ở đường hô hấp trên như viêm VA, viêm mũi xoang mạn tính, viêm amidan mạn tính quá phát hoặc dị hình vách ngăn gây ngạt mũi - tắc vòi nhĩ, dịch mủ và vi khuẩn từ mũi họng sẽ tiếp tục trào ngược lên hòm nhĩ làm nhiễm trùng hốc mổ và bong thủng mảnh ghép màng nhĩ. Do đó, điều kiện bắt buộc trước khi phẫu thuật tai có kế hoạch (ở VTG mạn không nguy hiểm hoặc VTG mạn chưa có biến chứng cấp cứu) là phải **Điều trị ổn định nguyên nhân ở mũi xoang, vòm họng trước rồi mới tiến hành phẫu thuật tai (C)**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Phẫu thuật tai trước rồi điều trị nguyên nhân sau - Sai ở VTG mạn thông thường): Nếu mổ vá nhĩ khi vòi nhĩ đang tắc và mũi xoang đang chảy mủ thì mảnh ghép sẽ hỏng. Phương án A chỉ áp dụng ngoại lệ khi bệnh nhân bị **VTG mạn tính nguy hiểm đang hồi viêm có biến chứng đe dọa tính mạng** (như áp xe não, viêm màng não, liệt dây VII) bắt buộc phải mổ tai cấp cứu ngay lập tức.\n- Phương án B (Phẫu thuật cùng một lúc - Không tối ưu đối với viêm mũi xoang mạn): Sau mổ mũi xoang thường phải nhét Merocel/bấc mũi gây tắc vòi nhĩ tạm thời và phù nề vùng vòm, nếu vá nhĩ cùng lúc sẽ ảnh hưởng xấu đến áp lực hòm nhĩ và sự liền mảnh ghép (chỉ có thể kết hợp nạo VA đơn giản ở trẻ em nếu chỉ đặt ống thông khí).\n- Phương án D (Không cần quan tâm yếu tố nguyên nhân - Sai hoàn toàn).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 4):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D, phản ánh đúng nguyên tắc kinh điển của Bộ môn TMH ĐHYHN về trình tự giải quyết nguyên nhân mũi xoang - vòm họng trước khi phẫu thuật tai giữa. Đáp án giữ nguyên là C."
