      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nBiến chứng xuất ngoại thể thái dương - mỏm tiếp (còn gọi là thể Luc) xảy ra khi quá trình viêm mủ ở nhóm thông bào vùng chân trai thái dương và gốc mỏm tiếp (phía trước trên ống tai ngoài) phá vỡ vỏ xương thoát ra vùng thái dương và hố thái dương nông. Đặc điểm lâm sàng kinh điển của thể này là: (1) Thường gặp ở **trẻ nhỏ dưới 1 tuổi (nhũ nhi)** khi sào bào nằm cao và các thông bào vùng mỏm tiếp phát triển sớm hơn mỏm chũm; (2) Khối sưng nề, tấy đỏ nằm ở vùng thái dương - trước trên tai, lan ra phía trước tới đuôi mắt làm **phù nề mi mắt cùng bên (D)**; (3) Vành tai bị đẩy **xuống dưới và ra ngoài** (khác với xuất ngoại sau tai đẩy vành tai ra trước và xuống dưới).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Vành tai đẩy lên trên, ra ngoài - Sai): Trong thể thái dương - mỏm tiếp, ổ áp xe nằm ở phía trên trước vành tai nên phải đẩy vành tai **xuống dưới và ra ngoài**.\n- Phương án B (Hay gặp ở trẻ lớn, người lớn - Sai): Thể thái dương - mỏm tiếp đặc trưng gặp ở **trẻ nhỏ < 1-2 tuổi** (khi mỏm chũm chưa phát triển, chỉ mới có sào bào và nhóm tế bào mỏm tiếp). Trẻ lớn và người lớn thường gặp thể xuất ngoại sau tai hoặc thể mỏm chũm (Bezold).\n- Phương án C (Dễ gây liệt mặt - Sai): Thể xuất ngoại dễ gây liệt dây thần kinh mặt (dây VII) sớm nhất là **Xuất ngoại thể ống tai ngoài (thể Gellé)** do mủ phá vỡ thành sau ống tai xương ngay sát đoạn 3 (đoạn chũm) của cống Fallope.",
