      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrong các biến chứng của Viêm tai giữa mạn tính nguy hiểm (bao gồm biến chứng nội sọ và biến chứng ngoại sọ), biến chứng có tỷ lệ tử vong cao nhất, tiên lượng nặng nề nhất và để lại di chứng thần kinh trầm trọng nhất là **Áp xe nội sọ (Áp xe đại não thùy thái dương và Áp xe tiểu não) (A)**. Đặc biệt áp xe tiểu não rất dễ gây tụt kẹt hạnh nhân tiểu não vào lỗ chẩm chèn ép hành não gây ngừng thở đột ngột tử vong. Biểu hiện lâm sàng của áp xe não do tai tuân theo tam chứng Bergman: (1) Hội chứng nhiễm trùng; (2) Hội chứng tăng áp lực nội sọ (đau đầu dữ dội, nôn vọt, mạch chậm huyết áp tăng, phù gai thị); (3) Hội chứng thần kinh khu trú (mất ngôn ngữ Wernicke, bán manh, liệt nửa người trong áp xe thùy thái dương; hoặc thất điều, rối loạn tầm độ, rung giật nhãn cầu trong áp xe tiểu não).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Liệt dây VII - Sai): Là biến chứng ngoại sọ/trong xương đá gây liệt mặt ngoại biên, ảnh hưởng thẩm mỹ và chức năng mắt/miệng nhưng không đe dọa trực tiếp tính mạng.\n- Phương án C (Viêm tĩnh mạch xoang bên - Sai): Tuy là biến chứng nội sọ nặng (gây nhiễm trùng huyết) nhưng tỷ lệ tử vong và nguy cơ tụt kẹt não tức thì thấp hơn áp xe đại não/tiểu não.\n- Phương án D (Xuất ngoại - Sai): Là biến chứng ngoại sọ lành tính nhất trong nhóm biến chứng xương chũm vì mủ đã thoát ra dưới da/cơ bên ngoài thay vì đi vào nội sọ.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là A."
