      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nỞ bệnh nhân Viêm tai giữa mạn tính, khi xuất hiện triệu chứng **đau tai sâu (hoặc đau nửa đầu) kèm chóng mặt quay cuồng**, nguyên nhân đầu tiên phải nghĩ tới là sự hiện diện và xâm lấn của khối **Cholesteatoma (A)** (trong Viêm tai giữa mạn tính nguy hiểm) đã ăn mòn thành xương của tai trong - thường gặp nhất là **ăn mòn ống bán khuyên ngoài (ngang)** gây rò mê nhĩ hoặc **biến chứng Viêm mê nhĩ (Labyrinthitis)**. Về giải phẫu, ống bán khuyên ngoài nằm lồi vào thành trong của sào đạo (ngay phía trên sau đoạn 2 của cống Fallope dây VII), do đó rất dễ bị khối cholesteatoma ở thượng nhĩ - sào đạo ăn mòn lớp vỏ xương cứng gây kích thích mê nhĩ màng, làm bệnh nhân chóng mặt, mất thăng bằng, buồn nôn, rung giật nhãn cầu (Nystagmus) và dấu hiệu rò (nghiệm pháp Lucae / ấn nắp bình tai gây chóng mặt và động mắt).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Áp xe tai giữa - Sai): Không có thuật ngữ 'áp xe tai giữa' gây chóng mặt trong VTG mạn đã thủng màng nhĩ dẫn lưu.\n- Phương án C (Tắc vòi nhĩ - Sai): Tắc vòi nhĩ chỉ gây ù tai tiếng trầm, cảm giác đầy nặng tai và nghe kém dẫn truyền nhẹ (như trong viêm tai giữa thanh dịch), không gây đau tai dữ dội kèm chóng mặt tiền đình ngoại biên.",
