      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nVề mặt giải phẫu và sinh lý dẫn lưu mũi xoang, các xoang cạnh mũi được chia thành 2 nhóm dựa trên vị trí lỗ thông tự nhiên đổ vào hốc mũi:\n- **Nhóm xoang trước** gồm 3 xoang: **(a) Xoang hàm trên, (b) Xoang trán và (c) Xoang sàng trước**. Cả 3 xoang này đều đổ vào **khe mũi giữa (ngách mũi giữa - nằm giữa cuốn mũi giữa và cuốn mũi dưới)** thông qua vùng phức hợp lỗ ngách (mỏm móc - bóng sàng - phễu sàng).\n- **Nhóm xoang sau** gồm 2 xoang: **(d) Xoang sàng sau** đổ vào **khe mũi trên** (nằm giữa cuốn mũi trên và cuốn mũi giữa); và **Xoang bướm** đổ vào **ngách bướm - sàng** (phía trên sau cuốn mũi trên). Do đó các xoang đổ vào khe giữa là a + b + c.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (a+c+d), C (a+b+d), D (b+c+d) (Đều sai vì chứa ý d - Xoang sàng sau): Xoang sàng sau không đổ vào khe mũi giữa mà đổ vào **khe mũi trên**.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 2):\nCâu hỏi gốc đầy đủ, rõ ràng, kiểm tra giải phẫu vị trí đổ của các xoang cạnh mũi. Đáp án giữ nguyên là A (a+b+c)."
