      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nPhân tích định khu tổn thương xoang dựa trên hình ảnh nội soi hốc mũi:\n- Nội soi thấy **có mủ chảy ra từ khe mũi giữa**: chứng tỏ có viêm của **nhóm xoang trước** (bao gồm **Xoang sàng trước (A), Xoang hàm trên (C), Xoang trán (D)**).\n- Nội soi thấy **có mủ chảy ra từ khe mũi trên** xuống sàn mũi ra cửa mũi sau: chứng tỏ có viêm của **Xoang sàng sau** (đổ vào khe mũi trên, đồng thời viêm xoang sàng sau cũng giải thích triệu chứng đau đầu âm ỉ vùng sâu/vùng chẩm của bệnh nhân).\n- Nội soi thấy **khe bướm - sàng (ngách bướm - sàng) hoàn toàn khô thoáng**: đây là vị trí đổ duy nhất của lỗ thông tự nhiên **Xoang bướm**. Do ngách bướm - sàng khô thoáng không có mủ nên xoang không bị viêm (hoặc ít khả năng viêm nhất) là **B. Xoang bướm**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A, C, D (Xoang sàng trước, Xoang hàm trên, Xoang trán - Đều có lỗ thông đổ vào khe mũi giữa nên đều nằm trong nhóm xoang nghi viêm khi thấy mủ ở khe mũi giữa).",
