      "hint": "Gợi ý (Lec 5: Viêm xoang (cấp)): Đối chiếu chuẩn kiến thức Lec 5: Viêm xoang (cấp) ĐHYHN. Đáp án chuẩn: B. Haemophilus influenzae.",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrong Viêm mũi xoang cấp tính nhiễm khuẩn ở trẻ em (và cả người lớn), 3 tác nhân vi khuẩn căn nguyên chiếm tỷ lệ cao nhất (khoảng 70-80% tổng số ca) là: *Streptococcus pneumoniae* (Phế cầu khuẩn) và ***Haemophilus influenzae* (không định týp - NTHi)**, tiếp theo là *Moraxella catarrhalis*. Đặc biệt sau khi vắc-xin phế cầu cộng hợp (PCV) được tiêm chủng rộng rãi ở trẻ em, tỷ lệ *Haemophilus influenzae* ngày càng chiếm ưu thế hàng đầu. Trong 4 phương án của câu hỏi (không có *S. pneumoniae*), **B. *Haemophilus influenzae*** là căn nguyên thường gặp nhất.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (*Streptococcus pyogenes* - Sai): Liên cầu khuẩn nhóm A chỉ chiếm tỷ lệ nhỏ (~3-5%) trong viêm mũi xoang cấp; đây là căn nguyên vi khuẩn hàng đầu của **Viêm họng - amidan cấp mủ** chứ không phải viêm mũi xoang cấp (nếu phương án A là *Streptococcus pneumoniae* thì mới cạnh tranh vị trí số 1 với *H. influenzae*).\n- Phương án C (*E. coli* - Sai): Trực khuẩn đường ruột Gram âm hiếm gặp trong viêm mũi xoang cấp cộng đồng ở trẻ khỏe mạnh.\n- Phương án D (*Moraxella catarrhalis* - Sai): Đứng hàng thứ 3 sau *S. pneumoniae* và *H. influenzae*.",
      "is_trap": true,
      "trap_note": "[Hiệu đính & Phân tích Bẫy Đề thi - Câu 54 (K117 - YK đợt 2)]: Hiệu đính chính tả ở phương án B: Sửa 'Hemophilus ìnluenza' thành 'Haemophilus influenzae'. Lưu ý dịch tễ vi sinh: bộ ba vi khuẩn gây viêm mũi xoang cấp hàng đầu ở trẻ em là Streptococcus pneumoniae (Phế cầu, ~30-40%), Haemophilus influenzae (~20-30%) và Moraxella catarrhalis (~15-20%). Trong đề thi này không có phương án Streptococcus pneumoniae (chỉ có A. Streptococcus pyogenes - liên cầu tan huyết beta nhóm A), do đó đáp án chuẩn xác nhất trong 4 lựa chọn là B. Haemophilus influenzae."
