      "hint": "Gợi ý (Lec 5: Viêm xoang (cấp)): Đối chiếu chuẩn kiến thức Lec 5: Viêm xoang (cấp) ĐHYHN. Đáp án chuẩn: B. Đau các vùng trên mặt tương ứng với các xoang cạnh mũi (nếu hỏi triệu chứng cơ năng đặc trưng) / C. Chảy dị.",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Tai Mũi Họng - Đại học Y Hà Nội, chẩn đoán Viêm mũi xoang cấp tính dựa vào các triệu chứng chính:\n1. **Về triệu chứng cơ năng**: Khác với viêm mũi cấp thông thường (chỉ có ngạt mũi và chảy mũi), triệu chứng cơ năng có giá trị nhất gợi ý tổn thương viêm cấp ở các xoang cạnh mũi là **Đau nhức vùng mặt tương ứng với vị trí giải phẫu của các xoang (B)** (đau vùng má/hố nanh lan lên răng hàm trên trong viêm xoang hàm; đau vùng giữa hai mắt trong viêm xoang sàng trước; đau nhức vùng trán - cung mày có chu kỳ từ 9h sáng đến 14h chiều trong viêm xoang trán), đau tăng khi cúi đầu hoặc ấn vào các điểm đau xoang (hố nanh, Grunwald, Ewing).\n2. **Về triệu chứng thực thể**: Khi soi mũi trước hoặc nội soi Tai Mũi Họng, dấu hiệu thực thể có giá trị chẩn đoán xác định cao nhất là thấy **dịch mủ chảy ra từ khe mũi giữa (C)** (đối với nhóm xoang trước) hoặc khe mũi trên/ngách bướm sàng (đối với nhóm xoang sau).\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Sốt cao, biểu hiện nhiễm trùng rõ - Sai): Sốt chỉ là triệu chứng toàn thân không đặc hiệu, gặp trong mọi nhiễm trùng cấp tính và trong VMX cấp do virus hoặc mức độ nhẹ có thể chỉ sốt nhẹ hoặc không sốt.\n- Phương án D (Ngạt mũi 2 bên - Sai): Ngạt mũi 2 bên gặp trong rất nhiều bệnh lý (viêm mũi cấp thông thường, viêm mũi dị ứng, quá phát cuốn dưới, polyp mũi 2 bên) nên độ đặc hiệu thấp.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nHiệu đính học thuật: Trong câu hỏi 'Triệu chứng có giá trị nhất của viêm mũi xoang cấp': nếu xét về **triệu chứng thực thể khi khám chuyên khoa** thì **C. Chảy dịch mủ từ khe giữa** trên nội soi là dấu hiệu khách quan đặc hiệu nhất khẳng định viêm xoang cấp mủ; còn nếu câu hỏi trong bài giảng hỏi về **triệu chứng cơ năng gợi ý định khu đặc trưng của viêm xoang cấp** (phân biệt với viêm mũi cấp thông thường chỉ có ngạt mũi, chảy mũi) thì giảng viên nhấn mạnh **B. Đau nhức các vùng trên mặt tương ứng với các xoang cạnh mũi** (đau có chu kỳ trong ngày). Ghi nhận cả B (theo đáp án gốc K117-PH về triệu chứng cơ năng đặc trưng) và C (dấu hiệu thực thể vàng trên nội soi) để đảm bảo chính xác tuyệt đối."
