      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nDo các xoang cạnh mũi có liên quan giải phẫu trực tiếp với hốc mắt (ngăn cách với xoang sàng qua xương giấy mỏng, với xoang trán qua trần ổ mắt, với xoang hàm qua sàn ổ mắt), với nền sọ và xoang tĩnh mạch hang (liên quan sát xoang bướm và xoang sàng sau), với dây thần kinh thị giác (chạy sát thành ngoài xoang bướm và tế bào sàng sau Onodi), và thông với tai giữa qua vòi nhĩ ở vòm mũi họng, nên các biến chứng của Viêm mũi xoang cấp bao gồm: (1) **Biến chứng mắt**: Viêm tấy trước vách, viêm tổ chức hốc mắt, áp xe dưới cốt mạc, **áp xe ổ mắt (B)**, **viêm dây thần kinh thị giác hậu nhãn cầu (D)**; (2) **Biến chứng nội sọ**: Viêm màng não, áp xe ngoài màng cứng/dưới màng cứng, áp xe não thùy trán, **viêm tắc tĩnh mạch xoang hang (A)**; (3) **Biến chứng đường hô hấp và kế cận**: Viêm tai giữa cấp (qua vòi nhĩ), viêm thanh khí phế quản, cốt tủy viêm xương hàm trên/xương trán. **Viêm tai ngoài (C)** hoàn toàn không phải là biến chứng của viêm mũi xoang cấp vì ống tai ngoài ngăn cách với tai giữa bởi màng nhĩ kín.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A, B, D (Đều là các biến chứng kinh điển và nguy hiểm của viêm mũi xoang cấp nên không chọn).\n- Phương án C (Sai - là đáp án cần chọn): Viêm mũi xoang cấp chỉ gây biến chứng **Viêm tai giữa cấp** (do mủ chảy xuống vòm mũi họng lan qua vòi Eustache lên hòm nhĩ), không gây viêm tai ngoài.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là C."
