      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrong chẩn đoán Viêm mũi xoang cấp tính (Acute Rhinosinusitis - ARS), **Nội soi Tai Mũi Họng (A)** là thăm khám lâm sàng/cận lâm sàng đầu tay, nhanh chóng, an toàn và có giá trị nhất giúp quan sát trực tiếp tình trạng phù nề niêm mạc phức hợp lỗ ngách và dòng mủ chảy ra từ khe mũi giữa hoặc khe mũi trên. Ngược lại, **Cắt lớp vi tính (CLVT) mũi xoang (B)** là xét nghiệm **không cần thiết trong viêm mũi xoang cấp không biến chứng** vì vừa gây phơi nhiễm tia xạ không cần thiết, vừa không phân biệt được viêm mũi xoang cấp do virus (cảm lạnh thông thường cũng gây mờ xoang trên CT ở > 80% trường hợp) với viêm mũi xoang cấp nhiễm khuẩn. CLVT mũi xoang chỉ được chỉ định trong VMX cấp khi có dấu hiệu báo động biến chứng ổ mắt hoặc biến chứng nội sọ.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Nội soi TMH - Cần thiết nhất nên không chọn): Là phương pháp thăm khám tiêu chuẩn để chẩn đoán xác định và định khu nhóm xoang viêm cấp (nhóm xoang trước hay nhóm xoang sau).\n- Phương án B (Sai / Không cần thiết nhất - là đáp án cần chọn): Chỉ trở thành cần thiết khi bệnh nhân bị **Viêm mũi xoang mạn tính (> 12 tuần)** hoặc **Viêm mũi xoang cấp có biến chứng**.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 2):\nHiệu đính bổ sung đáp án bị bỏ trống trong file gốc: Câu hỏi hỏi 'Xét nghiệm nào sau đây là không cần thiết nhất trong VMX cấp? A. Nội soi TMH / B. Cắt lớp vi tính mũi xoang'. Đáp án chuẩn xác 100% là **B. Cắt lớp vi tính mũi xoang**."
