      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Tai Mũi Họng - Đại học Y Hà Nội, vòng xoắn bệnh lý cốt lõi của Viêm mũi xoang là tình trạng phù nề niêm mạc gây **bít tắc lỗ thông tự nhiên của xoang (phức hợp lỗ ngách)** -> dẫn đến ứ đọng dịch tiết, giảm áp lực oxy trong lòng xoang, rối loạn vận chuyển hệ thống lông - nhầy (mucociliary clearance) và tạo môi trường cho vi khuẩn nhân lên. Vì vậy, nguyên tắc điều trị hàng đầu và xuyên suốt trong cả viêm mũi xoang cấp và mạn tính là **Phục hồi sự dẫn lưu và thông khí của xoang (A)** (bằng các biện pháp nội khoa tại chỗ như rửa mũi, thuốc co mạch ngắn ngày, corticoid tại chỗ; hoặc phẫu thuật nội soi chức năng mũi xoang FESS khi điều trị nội khoa thất bại trong VMX mạn), phối hợp chặt chẽ giữa điều trị tại chỗ và điều trị toàn thân.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Các phương án nhiễu (như chỉ dùng kháng sinh đơn thuần mà không giải quyết dẫn lưu thông khí tại chỗ, hoặc phẫu thuật ngay cho mọi ca viêm xoang cấp) đều sai vì nếu lỗ thông xoang vẫn bít tắc thì mủ không thoát ra được và bệnh không thể khỏi.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc khuyết các phương án nhiễu B, C, D (ví dụ: 'B. Phẫu thuật mở thông xoang ngay từ đầu', 'C. Dùng kháng sinh liều cao kéo dài cho mọi trường hợp', 'D. Chỉ điều trị triệu chứng toàn thân'). Đáp án chuẩn xác là A."
