      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nPhân tích tiêu chuẩn thời gian và tần suất của các thể Viêm mũi xoang theo Giáo trình TMH - ĐHYHN:\n- Đợt bệnh hiện tại của bệnh nhân kéo dài **3 tuần (> 10 ngày và < 12 tuần)** với triệu chứng **chảy mũi mủ xanh và hội chứng nhiễm trùng (+)** -> Đây là một đợt **Viêm mũi xoang cấp nhiễm khuẩn (B)**.\n- Tại sao KHÔNG chẩn đoán là 'Viêm mũi xoang cấp tái phát / tái diễn (Recurrent Acute Rhinosinusitis)'? Bởi vì theo định nghĩa chuẩn (EPOS & Giáo trình ĐHYHN), **Viêm mũi xoang cấp tái diễn** bắt buộc phải có **từ 4 đợt viêm mũi xoang cấp trở lên trong 1 năm (>= 4 đợt/năm)** và giữa các đợt bệnh nhân phải khỏi hoàn toàn không còn triệu chứng. Bệnh nhân này mới chỉ có 1 đợt cảm cúm tự khỏi cách đây 3 tháng (tức mới chỉ là đợt thứ 2 trong năm) nên chưa đủ tiêu chuẩn chẩn đoán thể tái diễn.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Viêm mũi xoang tái phát / tái diễn - Sai): Chỉ đúng khi bệnh nhân có tiền sử bị **>= 4 đợt viêm mũi xoang cấp/năm** và có các khoảng hoàn toàn bình thường giữa các đợt.\n- (Nếu có phương án Viêm mũi xoang mạn tính - Sai): VMX mạn tính đòi hỏi các triệu chứng phải kéo dài liên tục **>= 12 tuần (trên 3 tháng)** không khỏi hoàn toàn.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc khuyết phương án C, D (ví dụ: 'C. Viêm mũi xoang mạn tính', 'D. Viêm mũi xoang cấp do virus'). Đáp án chuẩn xác là B."
