      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Giáo trình Tai Mũi Họng - Đại học Y Hà Nội, các yếu tố giải phẫu tại chỗ thuận lợi gây cản trở sự dẫn lưu và thông khí của phức hợp lỗ ngách dẫn đến **Viêm mũi xoang mạn tính ở người lớn** thường gặp nhất là **Dị hình vách ngăn mũi (A)** (vẹo vách ngăn cao, mào vách ngăn, gai vách ngăn chèn ép vào cuốn mũi giữa làm hẹp khe mũi giữa), kèm theo các dị hình của cuốn mũi giữa (bóng khí cuốn giữa - Concha bullosa, cuốn giữa cong đảo chiều) hoặc quá phát mỏm móc, bóng sàng. Ngược lại, ở trẻ em, yếu tố thuận lợi hàng đầu gây viêm mũi xoang mạn tính là VA quá phát.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B, C (VA quá phát - Sai ở người lớn): Tổ chức VA (sùi vòm) phát triển mạnh ở trẻ từ 1-6 tuổi và thường teo nhỏ/thoái triển hoàn toàn sau tuổi dậy thì (12-15 tuổi), nên VA quá phát chỉ là nguyên nhân thường gặp ở **trẻ em**, rất hiếm gặp ở người lớn.\n- Phương án D (Dị hình khe giữa - Thuật ngữ không chuẩn): Khe mũi giữa là một khoảng trống (ngách), người ta chỉ gọi là dị hình vách ngăn hoặc dị hình các cấu trúc giải phẫu thành ngoài (mỏm móc, cuốn giữa, bóng sàng) gây hẹp khe giữa.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là A."
