      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrong chẩn đoán **Viêm mũi xoang mạn tính (Chronic Rhinosinusitis - CRS)**, cận lâm sàng chẩn đoán hình ảnh có giá trị nhất (tiêu chuẩn vàng về hình ảnh học) là **Chụp cắt lớp vi tính (CLVT / CT scan) mũi xoang (B)** trên hai bình diện Coronal (trán) và Axial (ngang) ở cửa sổ xương. CLVT mũi xoang cho phép: (1) Đánh giá chính xác mức độ dày niêm mạc, ứ đọng dịch/polyp trong từng xoang (thang điểm Lund-Mackay); (2) Khảo sát chi tiết cấu trúc giải phẫu của **phức hợp lỗ ngách (Ostiomeatal complex)** và các dị hình giải phẫu (vẹo vách ngăn, concha bullosa, tế bào Haller, tế bào Onodi); (3) Làm bản đồ giải phẫu bắt buộc (Road-map) cho phẫu thuật viên trước khi tiến hành phẫu thuật nội soi mũi xoang (FESS) để tránh làm tổn thương xương giấy (ổ mắt), trần sàng (nền sọ), động mạch cảnh trong và dây thần kinh thị giác.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (X-quang Blondeau - Sai): Phim X-quang quy ước bị chồng hình nhiều cấu trúc xương sọ mặt, hoàn toàn không nhìn thấy được phức hợp lỗ ngách và xoang sàng trước/sau.\n- Phương án C (MRI - Sai nếu dùng thường quy): MRI không hiển thị rõ các vách xương mỏng của mê đạo sàng và phức hợp lỗ ngách (những mốc xương sống còn cho phẫu thuật nội soi mũi xoang). MRI chỉ được chỉ định bổ sung khi nghi ngờ **khối u mũi xoang**, **viêm xoang do nấm xâm lấn** hoặc **biến chứng nội sọ/ổ mắt**.\n- Phương án D (Siêu âm - Sai): Sóng siêu âm không xuyên qua được các thành xương chứa khí của hệ thống xoang cạnh mũi.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là B."
