      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nChụp **Cắt lớp vi tính (CLVT) mũi xoang (C)** (ưu tiên mặt cắt Coronal vuông góc với sàn mũi và mặt cắt Axial) là xét nghiệm chẩn đoán hình ảnh chuẩn xác nhất để chẩn đoán xác định, đánh giá mức độ lan rộng của bệnh tích và lập kế hoạch phẫu thuật trong **Viêm mũi xoang mạn tính**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A, B (X-quang Blondeau, Hirtz - Sai): Là các tư thế X-quang cổ điển có độ nhạy và độ đặc hiệu thấp, không đánh giá được phức hợp lỗ ngách nên hiện nay đã được thay thế bởi CLVT mũi xoang.\n- Phương án D (MRI mũi xoang - Sai): Không phải là xét nghiệm thường quy để đánh giá cấu trúc xương mũi xoang trong viêm mũi xoang mạn tính thông thường.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi tương tự câu 69 ở đợt thi K117 đợt 1. Đáp án giữ nguyên là C."
