      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nPhương pháp có giá trị quyết định để chẩn đoán xác định và phân độ **Polyp mũi** trên lâm sàng là **Nội soi Tai Mũi Họng (nội soi mũi xoang bằng ống cứng 0 độ, 30 độ hoặc ống mềm) (A)**. Nội soi mũi xoang cho phép quan sát trực tiếp những khối polyp nhỏ ngay từ giai đoạn sớm (Polyp độ I còn nằm sâu trong khe mũi giữa/phức hợp lỗ ngách mà soi mũi trước bằng banh mũi thông thường không thể nhìn thấy), đánh giá chính xác đặc điểm đại thể của polyp (khối mềm, nhẵn bóng, màu trắng hồng hoặc xám nhạt, mọng nước như chùm nho, ấn bằng que thăm không đau và không dễ chảy máu) và phân độ polyp từ độ I đến độ IV.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Soi mũi trước - Kém chính xác hơn A): Soi mũi trước bằng gương trán và banh mũi chỉ nhìn thấy được polyp khi đã phát triển lớn (độ III, độ IV) thò ra phần trước hốc mũi, rất dễ bỏ sót polyp độ I, độ II nằm sâu trong khe mũi giữa hoặc vùng cửa mũi sau.\n- Phương án C, D (CLVT, MRI - Sai): Trên phim CLVT chỉ thấy hình ảnh mờ đục trong lòng xoang và hốc mũi, không thể nhìn trực tiếp màu sắc, bề mặt nhẵn bóng mọng nước để khẳng định polyp mũi nếu không kết hợp nội soi.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 3):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là A."
