      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nCác yếu tố nguy cơ chính gây Ung thư thanh quản theo Giáo trình TMH - ĐHYHN bao gồm: (1) **Hút thuốc lá, thuốc lào (B)** (yếu tố nguy cơ quan trọng hàng đầu, có mặt ở > 85-90% bệnh nhân K thanh quản); (2) **Uống rượu bia nhiều và kéo dài (C)** (đặc biệt khi phối hợp cả hút thuốc lá và uống rượu sẽ tạo tác dụng hiệp đồng nhân lên nguy cơ mắc K thanh quản và K hạ họng gấp 15-40 lần); (3) **Tiền sử chiếu xạ vùng cổ (D)**; (4) Nhiễm virus HPV (týp 16, 18), hội chứng trào ngược họng - thanh quản (LPR/GERD) mạn tính, tiếp xúc nghề nghiệp với bụi amiăng (asbestos), hóa chất, hơi acid, bụi gỗ. Trong khi đó, thói quen **Nhai trầu (A)** (trầu cau + vôi + thuốc lào) tiếp xúc trực tiếp với niêm mạc miệng nên là yếu tố nguy cơ đặc hiệu của **Ung thư khoang miệng (ung thư niêm mạc má, lợi, sàn miệng, lưỡi)** chứ không phải ung thư thanh quản.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Sai - là đáp án cần chọn): Nhai trầu là yếu tố nguy cơ hàng đầu của **Ung thư khoang miệng (đặc biệt là K niêm mạc má)**.\n- Phương án B, C, D (Đều là các yếu tố nguy cơ đã được chứng minh của ung thư thanh quản nên không chọn).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là A."
