      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\n**Nang dây thanh (Vocal cord cyst) (A)** (bao gồm nang ứ đọng chất nhầy hoặc nang biểu bì nằm trong lớp đệm nông - khoang Reinke của dây thanh) là một tổn thương giả u / lành tính hoàn toàn của dây thanh liên quan đến lạm dụng giọng nói hoặc bít tắc tuyến nhầy, **hoàn toàn KHÔNG phải là yếu tố nguy cơ hay tổn thương tiền ung thư của thanh quản**. Ngược lại, thuốc lá (B), rượu (C) và tiền sử chiếu xạ vùng cổ (D) đều là các yếu tố nguy cơ kinh điển gây ung thư thanh quản.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Sai - là đáp án cần chọn): Nang dây thanh chỉ là nguyên nhân gây khàn tiếng lành tính điều trị khỏi hoàn toàn bằng vi phẫu thanh quản bóc nang kết hợp luyện giọng.\n- Phương án B, C, D (Đều là các yếu tố nguy cơ của K thanh quản nên không chọn).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D, biến thể của câu 79. Đáp án giữ nguyên là A."
