      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\n**Bạch sản dây thanh (Vocal cord leukoplakia) (A)** là một tổn thương **tiền ung thư (Precancerous lesion)** điển hình nhất của thanh quản, biểu hiện trên nội soi là các mảng hoặc đám màu trắng đục, dày sừng bám chặt trên bề mặt niêm mạc dây thanh (không bong ra khi quệt). Về mặt mô bệnh học, vùng bạch sản dây thanh thường chứa các mức độ **loạn sản biểu mô (Dysplasia)** từ độ nhẹ, vừa, nặng cho đến **Ung thư biểu mô tại chỗ (Carcinoma in situ - Tis)** hoặc thậm chí đã có ổ ung thư biểu mô vảy xâm lấn vi thể bên dưới lớp sừng hóa. Do đó, phát hiện bạch sản dây thanh trên nội soi là dấu hiệu nghi ngờ cao nhất của K thanh quản hoặc tiền K thanh quản, bắt buộc phải soi treo thanh quản vi phẫu cắt/sinh thiết toàn bộ mảng bạch sản làm giải phẫu bệnh.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Polyp dây thanh - Sai): Polyp dây thanh là tổn thương giả u lành tính ở khoang Reinke, không phải tổn thương tiền ung thư.\n- Phương án C (U nhú thanh quản - Nguy cơ thấp hơn Bạch sản): U nhú thanh quản do HPV (đặc biệt ở trẻ em) đa số là lành tính; chỉ u nhú ở người lớn tái phát nhiều lần nhiễm HPV týp 16, 18 mới có nguy cơ ác tính hóa nhưng tỷ lệ thấp hơn nhiều so với bạch sản/loạn sản dây thanh.\n- Phương án D (Lao hạt kê - Sai): Là bệnh lý nhiễm vi khuẩn lao (*Mycobacterium tuberculosis*) lan tràn đường máu, không phải tổn thương tiền ung thư.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D (nằm trong cụm câu hỏi 81-83 về tổn thương tiền ung thư thanh quản). Đáp án giữ nguyên là A."
