      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nCác triệu chứng cơ năng của Ung thư thanh quản gắn liền với chức năng phát âm, thở và bảo vệ đường thở của thanh quản, bao gồm: **Khàn tiếng** (triệu chứng chính và xuyên suốt), **ho kích thích, ho khạc đờm lẫn máu tươi** (do khối u sùi loét chảy máu), **khó thở thanh quản** (khi u to làm hẹp thanh môn), và **nuốt đau/nuốt vướng kèm khàn tiếng** (khi u ở thượng thanh môn hoặc lan ra hạ họng). Do đó các tổ hợp triệu chứng B ('Nuốt đau, khàn tiếng'), C ('Khàn tiếng, ho') và D ('Ho khạc máu, khó thở') đều là các bệnh cảnh điển hình của ung thư thanh quản. Ngược lại, tổ hợp **'A. Nuốt vướng, đau vùng cổ'** đơn thuần (không có bất kỳ triệu chứng nào của thanh quản - đường thở như khàn tiếng hay khó thở) không phải là triệu chứng đặc trưng của ung thư thanh quản mà gợi ý bệnh lý thực quản (dị vật thực quản, áp xe quanh thực quản) hoặc tuyến giáp / phần mềm cổ.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án A (Sai - là đáp án cần chọn): Phương án này sẽ đúng khi hỏi về triệu chứng của **Dị vật thực quản cổ / Viêm tấy quanh thực quản** hoặc **Viêm tuyến giáp bán cấp De Quervain**.\n- Phương án B (Nuốt đau, khàn tiếng - Đúng cho K thượng thanh môn lan xuống dây thanh hoặc K thanh môn lan rộng).\n- Phương án C (Khàn tiếng, ho - Đúng cho K thanh quản giai đoạn sớm - trung bình).\n- Phương án D (Ho khạc máu, khó thở - Đúng cho K thanh quản giai đoạn tiến triển có loét chảy máu và hẹp thanh môn).\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 3):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là A."
