      "hint": "Gợi ý (Lec 7: K thanh quản (chẩn đoán)): Đối chiếu chuẩn kiến thức Lec 7: K thanh quản (chẩn đoán) ĐHYHN. Đáp án chuẩn: A. Dấu hiệu 'Mai rùa' (sụn giáp to bè, biến dạng do u phá vỡ sụn giáp xâm lấn ra ngoài).",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTrong Ung thư thanh quản giai đoạn muộn (giai đoạn **T4a** theo phân loại TNM của AJCC), khối u phát triển lớn phá hủy và xuyên qua **vỏ sụn giáp (thyroid cartilage)** hoặc màng nhẫn - giáp để xâm lấn ra các cơ dưới móng và tổ chức phần mềm trước thanh quản. Khi khám thực thể vùng cổ (nhìn và sờ nắn thanh quản), thầy thuốc sẽ thấy hai cánh sụn giáp bị đẩy phồng to bè ra hai bên, mất góc nhọn của lồi thanh quản (trái lộ hầu), mật độ cứng chắc, sần sùi, bờ không đều, tạo nên hình ảnh kinh điển gọi là **Dấu hiệu 'Mai rùa' (A)**. Ngoài ra, nếu khối u xâm lấn ra phía sau vào khớp nhẫn - phễu, cơ khít họng và mặt trước cột sống cổ sẽ làm thanh quản bị cố định, khi lắc thanh quản sang hai bên sẽ thấy **mất tiếng lọc cọc thanh quản - cột sống (dấu hiệu Moure âm tính)**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Hạn chế vận động cổ - Sai): Hạn chế vận động cột sống cổ gặp trong bệnh lý cột sống cổ, viêm tấy lan tỏa khoang sau họng hoặc khi có khối hạch cổ N3 khổng lồ xâm lấn cơ ức đòn chũm và cơ sâu vùng cổ, không phải dấu hiệu đặc hiệu trực tiếp tại thanh quản khi u phá vỡ sụn giáp.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 1):\nCâu hỏi gốc khuyết phương án C, D (ví dụ: 'C. Khàn tiếng nhẹ', 'D. Phù nề mi mắt'). Lưu ý thuật ngữ kinh điển của Bộ môn TMH ĐHYHN: khi khối u thanh quản phá vỡ sụn giáp lan ra phần mềm trước cổ sẽ tạo nên **dấu hiệu 'Mai rùa' (hoặc sụn giáp to bè như mai rùa/mu rùa)** kèm theo **mất tiếng lọc cọc thanh quản - cột sống (dấu hiệu Moure âm tính)** khi u lan ra phía sau. Đáp án chuẩn xác là A."
