      "hint": "Gợi ý (Lec 8: K thanh quản (điều trị)): Đối chiếu chuẩn kiến thức Lec 8: K thanh quản (điều trị) ĐHYHN. Đáp án chuẩn: A. Thanh quản điện.",
      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nSau phẫu thuật cắt thanh quản toàn phần (Total laryngectomy), đường thở (khí quản được đưa ra mở thông trực tiếp ở da vùng cổ trước) và đường ăn (họng - thực quản) bị tách rời hoàn toàn, bệnh nhân mất đi nguồn rung âm thanh từ hai dây thanh nên mất khả năng nói bình thường. Theo Giáo trình Tai Mũi Họng - Đại học Y Hà Nội, có 3 phương pháp chính giúp phục hồi giọng nói cho bệnh nhân sau cắt thanh quản toàn phần:\n1. **Sử dụng Thanh quản điện (Electrolarynx) (A)**: Là thiết bị phát dao động cơ học cầm tay áp vào vùng da dưới cằm / thành bên cổ; dao động truyền qua mô mềm vào khoang họng - miệng và được bệnh nhân cấu âm bằng lưỡi, môi, màn hầu thành lời nói.\n2. **Tập nói giọng thực quản (Esophageal speech)**: Bệnh nhân nuốt không khí vào phần trên thực quản rồi ợ luồng khí đó ra làm rung cơ thắt thực quản trên (đoạn họng - thực quản) để phát âm.\n3. **Đặt van phát âm khí - thực quản (Tracheoesophageal voice prosthesis - như van Provox, Blom-Singer)**: Tạo một lỗ rò nhỏ giữa thành sau khí quản và thành trước thực quản có gắn van một chiều; khi bệnh nhân bịt lỗ thở khí quản ở cổ và thở ra, luồng khí từ phổi đi qua van vào thực quản - họng tạo ra giọng nói gần tự nhiên nhất.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B, C, D (Thực quản điện, Khí quản điện, Phế quản điện - Đều là các tên gọi hư cấu không tồn tại trong y học; đối với thực quản chỉ có 'Giọng nói thực quản tự tập' hoặc 'Van phát âm khí - thực quản').\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - PH):\nCâu hỏi gốc đầy đủ 4 phương án A, B, C, D. Đáp án giữ nguyên là A."
