      "exp": "📖 GIẢI THÍCH CHI TIẾT ĐÁP ÁN ĐÚNG (GIÁO TRÌNH ĐHYHN & BỘ Y TẾ):\nTheo Hướng dẫn chẩn đoán và điều trị Ung thư thanh quản (Bộ môn TMH - ĐHYHN và NCCN Guidelines), đối với ung thư thanh quản giai đoạn tiến triển tại chỗ **T4aN0M0** (khối u đã phá vỡ vỏ ngoài sụn giáp và/hoặc xâm lấn các cấu trúc ngoài thanh quản như sụn nhẫn, khí quản, cơ dưới móng, tuyến giáp, phần mềm trước cổ), các phương pháp bảo tồn thanh quản (như cắt thanh quản bán phần, cắt laser qua đường miệng hay xạ trị đơn thuần) đều bị chống chỉ định vì tỷ lệ tái phát tại chỗ rất cao và sụn giáp đã bị phá hủy (xạ trị trên sụn bị u xâm lấn dễ gây hoại tử sụn thanh quản nặng nề). Do đó, phương pháp điều trị tiêu chuẩn là **Phẫu thuật cắt thanh quản toàn phần kết hợp nạo vét hạch cổ (dự phòng/chọn lọc nhóm II-IV và nhóm VI) (A)**, sau đó **xạ trị (hoặc hóa - xạ trị) bổ trợ hậu phẫu**.\n\n🔍 PHÂN TÍCH TẠI SAO CÁC PHƯƠNG ÁN KHÁC SAI & TRƯỜNG HỢP ÁP DỤNG:\n- Phương án B (Phẫu thuật cắt thanh quản bán phần + nạo vét hạch - Sai): Cắt thanh quản bán phần chỉ áp dụng cho giai đoạn sớm **T1, T2** (và một số ca T3 chọn lọc rất kỹ khi sụn giáp chưa bị phá hủy và khớp nhẫn - phễu còn bảo tồn được ít nhất 1 đơn vị chức năng).\n- Phương án C (Phẫu thuật Laser CO2 qua đường miệng - Sai): Chỉ định cho ung thư dây thanh giai đoạn rất sớm **Tis, T1a, T1b hoặc T2 nông**.\n\n🛠️ HIỆU ĐÍNH ĐỀ & ĐỐI CHIẾU ĐÁP ÁN GỐC (K117 - YK đợt 3):\nCâu hỏi gốc khuyết phương án D (ví dụ: 'D. Xạ trị đơn thuần'). Đáp án chuẩn xác là A."
